CREATE TABLE payments (id UUID PRIMARY KEY, amount NUMERIC(19,2) NOT NULL, currency VARCHAR(3) NOT NULL, merchant_reference VARCHAR(100) NOT NULL, customer_id VARCHAR(100) NOT NULL, payment_token VARCHAR(100) NOT NULL, status VARCHAR(20) NOT NULL, failure_reason VARCHAR(255), version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE idempotency_records (id UUID PRIMARY KEY, idempotency_key VARCHAR(255) NOT NULL UNIQUE, request_hash VARCHAR(64) NOT NULL, resource_type VARCHAR(30) NOT NULL, resource_id UUID, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE payment_transitions (id UUID PRIMARY KEY, payment_id UUID NOT NULL REFERENCES payments(id), from_status VARCHAR(20), to_status VARCHAR(20) NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE ledger_entries (id UUID PRIMARY KEY, payment_id UUID NOT NULL REFERENCES payments(id), entry_type VARCHAR(10) NOT NULL, account VARCHAR(60) NOT NULL, amount NUMERIC(19,2) NOT NULL, currency VARCHAR(3) NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE outbox_events (id UUID PRIMARY KEY, aggregate_id UUID NOT NULL, event_type VARCHAR(50) NOT NULL, payload TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, published_at TIMESTAMPTZ);
CREATE INDEX idx_ledger_payment ON ledger_entries(payment_id); CREATE INDEX idx_outbox_unpublished ON outbox_events(published_at) WHERE published_at IS NULL;
